-- interview-fix-diagrams.sql — 補回 q5/q6/q13 被剝掉的電路圖（zh + en）
-- 背景：interview-questions-seed.sql 抽取時 SVG 被剝掉，DB 只剩空的
--       <div class="exam-diagram-box"></div>；ja/ko（interview-i18n.sql）反而有圖。
-- 產生器：scratchpad/gen-fix-diagrams.js（來源 = interview-bank.js，已上線驗證過的圖）
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。
--       可重複執行：marker 被換掉後 replace() 找不到目標，第二次跑不會有副作用。

-- q5：IO 輸出架構：Push-Pull vs Open-Drain（SVG 3563 chars）
update public.interview_questions
   set answer    = replace(answer,    $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg width="520" height="224" viewBox="0 0 520 224" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="224" fill="#0a0a1a"/><text x="260" y="20" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Push-Pull vs Open-Drain Output</text><line x1="260" y1="46" x2="260" y2="184" stroke="#334155" stroke-width="1"/><text x="130" y="38" fill="#ffc107" font-size="12" font-weight="bold" text-anchor="middle">Push-Pull</text><line x1="130" y1="52" x2="130" y2="64" stroke="#ff6b6b" stroke-width="1.6"/><text x="138" y="60" fill="#ff6b6b" font-size="11">VDD</text><rect x="112" y="64" width="36" height="26" rx="3" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="130" y="81" fill="#00ff88" font-size="11" text-anchor="middle">P</text><line x1="130" y1="90" x2="130" y2="130" stroke="#ffc107" stroke-width="2"/><circle cx="130" cy="110" r="3" fill="#ffc107"/><line x1="130" y1="110" x2="178" y2="110" stroke="#ffc107" stroke-width="2"/><text x="182" y="114" fill="#ffc107" font-size="11">OUT</text><rect x="112" y="130" width="36" height="26" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="130" y="147" fill="#00d4ff" font-size="11" text-anchor="middle">N</text><line x1="130" y1="156" x2="130" y2="172" stroke="#888" stroke-width="1.6"/><line x1="112" y1="172" x2="148" y2="172" stroke="#888" stroke-width="1.6"/><line x1="118" y1="177" x2="142" y2="177" stroke="#888" stroke-width="1.4"/><line x1="124" y1="182" x2="136" y2="182" stroke="#888" stroke-width="1.2"/><text x="152" y="180" fill="#888" font-size="11">GND</text><line x1="66" y1="110" x2="112" y2="77" stroke="#666" stroke-width="1" stroke-dasharray="3"/><line x1="66" y1="110" x2="112" y2="143" stroke="#666" stroke-width="1" stroke-dasharray="3"/><text x="60" y="114" fill="#888" font-size="11" text-anchor="end">IN</text><text x="10" y="196" fill="#00ff88" font-size=