   set answer    = replace(answer,    $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg width="520" height="254" viewBox="0 0 520 254" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="254" fill="#0a0a1a"/><text x="260" y="20" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">I2C Bus: open-drain + pull-ups</text><line x1="180" y1="46" x2="250" y2="46" stroke="#ff6b6b" stroke-width="1.6"/><text x="215" y="40" fill="#ff6b6b" font-size="11" text-anchor="middle">VDD</text><line x1="180" y1="46" x2="180" y2="58" stroke="#ff6b6b" stroke-width="1.6"/><line x1="250" y1="46" x2="250" y2="58" stroke="#ff6b6b" stroke-width="1.6"/><rect x="162" y="58" width="36" height="24" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="180" y="74" fill="#ffc107" font-size="11" text-anchor="middle">Rp</text><rect x="232" y="58" width="36" height="24" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="250" y="74" fill="#ffc107" font-size="11" text-anchor="middle">Rp</text><line x1="180" y1="82" x2="180" y2="104" stroke="#888" stroke-width="1.4"/><line x1="250" y1="82" x2="250" y2="132" stroke="#888" stroke-width="1.4"/><line x1="70" y1="104" x2="460" y2="104" stroke="#00d4ff" stroke-width="2"/><line x1="70" y1="132" x2="460" y2="132" stroke="#ffc107" stroke-width="2"/><text x="64" y="100" fill="#00d4ff" font-size="11" text-anchor="end">SCL</text><text x="64" y="128" fill="#ffc107" font-size="11" text-anchor="end">SDA</text><circle cx="180" cy="104" r="3" fill="#00d4ff"/><circle cx="250" cy="132" r="3" fill="#ffc107"/><rect x="80" y="168" width="90" height="40" rx="4" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="125" y="192" fill="#00ff88" font-size="11" text-anchor="middle">Master</text><rect x="210" y="168" width="90" height="40" rx="4" fill="none" stroke="#888" stroke-width="1.6"/><text x="255" y="192" fill="#888" font-size="11" text-anchor="middle">Slave 1</text><rect x="340" y="168" width="90" height="40" rx="4" fill="none" stroke="#888" stroke-width="1.6"/><text x="385" y="192" fill="#888" font-size="11" text-anchor="middle">Slave 2</text><line x1="100" y1="168" x2="100" y2="104" stroke="#888" stroke-width="1.4"/><line x1="140" y1="168" x2="140" y2="132" stroke="#888" stroke-width="1.4"/><line x1="230" y1="168" x2="230" y2="104" stroke="#888" stroke-width="1.4"/><line x1="270" y1="168" x2="270" y2="132" stroke="#888" stroke-width="1.4"/><line x1="360" y1="168" x2="360" y2="104" stroke="#888" stroke-width="1.4"/><line x1="400" y1="168" x2="400" y2="132" stroke="#888" stroke-width="1.4"/><circle cx="100" cy="104" r="2.5" fill="#00d4ff"/><circle cx="230" cy="104" r="2.5" fill="#00d4ff"/><circle cx="360" cy="104" r="2.5" fill="#00d4ff"/><circle cx="140" cy="132" r="2.5" fill="#ffc107"/><circle cx="270" cy="132" r="2.5" fill="#ffc107"/><circle cx="400" cy="132" r="2.5" fill="#ffc107"/><text x="10" y="224" fill="#888" font-size="11">SCL: master clocks it, but any slave may hold it LOW = clock stretching</text><text x="10" y="244" fill="#888" font-size="11">SDA: bidirectional, wire-AND arbitration. Cb(total) &lt;= 400pF</text></svg></div>$vsq$),
       answer_en = replace(answer_en, $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg width="520" height="254" viewBox="0 0 520 254" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="254" fill="#0a0a1a"/><text x="260" y="20" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">I2C Bus: open-drain + pull-ups</text><line x1="180" y1="46" x2="250" y2="46" stroke="#ff6b6b" stroke-width="1.6"/><text x="215" y="40" fill="#ff6b6b" font-size="11" text-anchor="middle">VDD</text><line x1="180" y1="46" x2="180" y2="58" stroke="#ff6b6b" stroke-width="1.6"/><line x1="250" y1="46" x2="250" y2="58" stroke="#ff6b6b" stroke-width="1.6"/><rect x="162" y="58" width="36" height="24" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="180" y="74" fill="#ffc107" font-size="11" text-anchor="middle">Rp</text><rect x="232" y="58" width="36" height="24" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="250" y="74" fill="#ffc107" font-size="11" text-anchor="middle">Rp</text><line x1="180" y1="82" x2="180" y2="104" stroke="#888" stroke-width="1.4"/><line x1="250" y1="82" x2="250" y2="132" stroke="#888" stroke-width="1.4"/><line x1="70" y1="104" x2="460" y2="104" stroke="#00d4ff" stroke-width="2"/><line x1="70" y1="132" x2="460" y2="132" stroke="#ffc107" stroke-width="2"/><text x="64" y="100" fill="#00d4ff" font-size="11" text-anchor="end">SCL</text><text x="64" y="128" fill="#ffc107" font-size="11" text-anchor="end">SDA</text><circle cx="180" cy="104" r="3" fill="#00d4ff"/><circle cx="250" cy="132" r="3" fill="#ffc107"/><rect x="80" y="168" width="90" height="40" rx="4" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="125" y="192" fill="#00ff88" font-size="11" text-anchor="middle">Master</text><rect x="210" y="168" width="90" height="40" rx="4" fill="none" stroke="#888" stroke-width="1.6"/><text x="255" y="192" fill="#888" font-size="11" text-anchor="middle">Slave 1</text><rect x="340" y="168" width="90"