-- q13：Buck 上管 ON / OFF 電流路徑（SVG 4150 chars）
update public.interview_questions
   set answer    = replace(answer,    $box$<div class="exam-diagram-box"></div>$box$, $vsq$<div class="exam-diagram-box"><svg width="520" height="224" viewBox="0 0 520 224" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="224" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Buck Current Path (yellow = conducting loop)</text><path d="M44,50 H76 V92 H170 V158 H58" fill="none" stroke="#eab308" stroke-width="7" stroke-opacity="0.35" stroke-linecap="round" stroke-linejoin="round"/><text x="98" y="34" fill="#00ff88" font-size="11" font-weight="bold" text-anchor="middle">Phase 1: HS ON, LS OFF</text><text x="12" y="44" fill="#ff6b6b" font-size="11">VIN</text><line x1="42" y1="50" x2="58" y2="50" stroke="#ff6b6b" stroke-width="1.6"/><rect x="58" y="38" width="36" height="24" rx="3" fill="none" stroke="#00ff88" stroke-width="1.6"/><text x="76" y="54" fill="#00ff88" font-size="11" text-anchor="middle">HS</text><line x1="76" y1="62" x2="76" y2="104" stroke="#ffc107" stroke-width="2"/><text x="50" y="88" fill="#ffc107" font-size="11" text-anchor="end">SW</text><line x1="76" y1="92" x2="92" y2="92" stroke="#ffc107" stroke-width="2"/><rect x="92" y="82" width="46" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="115" y="97" fill="#00d4ff" font-size="11" text-anchor="middle">L</text><line x1="138" y1="92" x2="170" y2="92" stroke="#888" stroke-width="1.6"/><circle cx="170" cy="92" r="3" fill="#888"/><line x1="170" y1="92" x2="170" y2="112" stroke="#888" stroke-width="1.6"/><rect x="152" y="112" width="36" height="28" rx="3" fill="none" stroke="#888" stroke-width="1.6"/><text x="170" y="131" fill="#888" font-size="11" text-anchor="middle">Load</text><line x1="170" y1="140" x2="170" y2="158" stroke="#888" stroke-width="1.6"/><rect x="58" y="104" width="36" height="24" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="76" y="120" fill="#00d4ff" font-size="11" text-anchor="middle"